  const days=str(raw[source.key==='swim'?'요일':'수강요일']);let target=str(raw[source.key==='swim'?'강습반':'수강대상']),targetSource=target?'수강대상 항목':'미기재';
  if(!target){target=[...new Set(item.title.match(/성인|청소년|어린이|초등|유아|여성|주부/g)||[])].join('·');if(target)targetSource='강좌명 표기';}
