  const versions=Object.entries(spec.paths||{}).map(([path,value])=>({path,title:value.get?.summary||'',date:parseDate((value.get?.summary||'').match(/\d{8}(?!.*\d{8})/)?.[0])})).filter(x=>new RegExp('^/'+source.namespace+'/v1/uddi:[a-f0-9-]+$').test(x.path)&&x.date).sort((a,b)=>b.date.localeCompare(a.date));
